"""Hand-authored curricula for ten browser and styling topics."""
import runpy
from pathlib import Path
api = runpy.run_path(str(Path(__file__).with_name('author-web.py')))
L, build = api['lesson'], api['build']

build('sass',
 'Sass helps you write CSS with reusable names and recipes. A build tool turns your Sass into normal CSS. Start with a colour, then learn to share styles without copying the same lines.',
 'Use Dart Sass on your computer. Install Node.js first, with help if needed. Save SCSS examples as lesson.scss and run npx sass lesson.scss lesson.css. This site does not compile Sass.',
 'Uses Dart Sass and the SCSS syntax, with the modern @use module system.', [
 L('Set up the Sass tool', 'Sass is a tool that turns a style recipe into CSS. The browser reads the CSS file, so it does not need to understand the Sass recipe.', 'bash', 'npm install --save-dev sass\nnpx sass --version', 'The first command adds Sass to a local project. The second prints its version number.', 'Run these commands in a project folder. A .scss file is not a CSS file that a browser can read directly.', 'Find the version number printed by the Sass tool.', 'Which file does the browser read after Sass builds your styles?', 'The CSS output file', 'The unbuilt SCSS recipe', slug='introduction'),
 L('Name a colour', 'A Sass variable gives a value a name. The dollar sign starts that name. You can reuse one colour without typing its code each time.', 'scss', '$ink: #174a8b;\nh1 { color: $ink; }\na { color: $ink; }', 'Both h1 and a rules use #174a8b in the CSS output. The $ink name is replaced during the build.', 'A Sass variable is chosen while building CSS. It is different from a CSS custom property that the browser can change.', 'Change the ink colour and rebuild the CSS file.', 'What starts a Sass variable name?', 'A dollar sign, such as $ink', 'A dot, such as .ink'),
 L('Nest a simple rule', 'Nesting puts a rule inside another rule. Sass joins the selectors. This can show that a small part belongs inside a bigger part.', 'scss', '.card {\n  padding: 1rem;\n  h2 { color: navy; }\n}', 'The output styles .card and .card h2. Only headings inside a card get the navy colour.', 'Too many nesting levels make hard-to-change selectors. Keep this example one level deep.', 'Add a nested p rule that sets a text colour.', 'Which heading does the nested h2 rule choose?', 'An h2 inside .card', 'Every h2 on every page'),
 L('Use the parent sign', 'The ampersand sign stands for the selector around it. It is useful when the same element changes state, such as a button being focused.', 'scss', '.button {\n  color: navy;\n  &:focus-visible { outline: 3px solid orange; }\n}', 'Sass creates .button:focus-visible. A keyboard user can see a clear outline when the button receives focus.', 'Without &, a nested :focus-visible would choose a focused child instead of the button itself.', 'Change the focus outline to a different visible colour.', 'What does & stand for in this nested rule?', 'The surrounding .button selector', 'All elements on the page'),
 L('Make a mixin recipe', 'A mixin is a named group of CSS choices. Include it wherever you want those choices copied into a rule.', 'scss', '@mixin soft-box {\n  padding: 1rem;\n  border-radius: 0.5rem;\n}\n.card { @include soft-box; }\n.note { @include soft-box; }', 'Both classes get padding and round corners. Changing the recipe changes both after the next build.', 'Defining a mixin does not output a style by itself. Use @include to put it into a rule.', 'Include soft-box inside one more class named tip.', 'Which command uses a mixin?', '@include soft-box', '@use soft-box as a property'),
 L('Give a mixin an input', 'A mixin can take an input value. A default value is used when the caller does not provide one.', 'scss', '@mixin frame($colour: navy) { border: 2px solid $colour; }\n.book { @include frame; }\n.game { @include frame(green); }', 'The book border is navy. The game border is green because its call supplies a different input.', 'Put the input inside parentheses. A class named green is not the same thing as a colour value.', 'Give the game frame an orange border.', 'Which colour does frame use when no input is given?', 'Navy, its default value', 'It chooses a random colour'),
 L('Share a module', 'A module is a Sass file that shares values or recipes. @use loads it and gives its members a clear name prefix.', 'scss', '// _colours.scss\n$ink: navy;\n\n// lesson.scss, in the same folder\n@use "colours";\nh1 { color: colours.$ink; }', 'Save the two labelled sections as separate files. Building lesson.scss makes a navy h1 rule.', 'Keep @use at the start of the file. Do not paste both file sections into one file without splitting them.', 'Add a second colour to _colours.scss and use it.', 'How do you read ink from the colours module?', 'colours.$ink', '$colours.ink'),
 L('Do simple Sass maths', 'The Sass math module has tools for calculations. math.div divides values while Sass builds the stylesheet.', 'scss', '@use "sass:math";\n$space: 24px;\n.card { padding: math.div($space, 2); }', 'The card gets 12px of padding. Sass does the division before the browser loads the page.', 'Use math.div for Sass division. A slash can have another meaning in CSS values.', 'Change space to 32px and work out the new padding.', 'What is math.div(24px, 2)?', '12px', '48px'),
 L('Use a colour map', 'A map pairs names with values, like labels on paint pots. map.get looks up the value for one label.', 'scss', '@use "sass:map";\n$colours: ("sea": teal, "sun": gold);\n.note { background: map.get($colours, "sun"); }', 'The note background is gold. The key sun selects that entry from the map.', 'Use a key that exists. A missing key gives null, so the expected style may be left out.', 'Change the lookup from sun to sea.', 'Which value is stored under the key sun?', 'gold', 'teal'),
 L('Repeat a small rule', 'An @each loop makes one rule for each item in a list. It saves repeated typing when the rule shape stays the same.', 'scss', '@each $size in 1, 2, 3 {\n  .space-#{$size} { margin: $size * 4px; }\n}', 'The output has space-1 with 4px, space-2 with 8px and space-3 with 12px margins.', 'The #{} form inserts a value into a selector name. Do not generate hundreds of unused classes.', 'Add 4 to the list and predict the new margin.', 'How much margin does space-3 get?', '12px', '3px'),
 L('Write a small function', 'A Sass function calculates one value and returns it. A mixin writes a group of declarations instead.', 'scss', '@function gap($steps) { @return $steps * 4px; }\n.card { padding: gap(3); }', 'The card padding becomes 12px. The return value fits where an ordinary CSS value would go.', 'A function needs @return. Use a mixin when you want to output several properties.', 'Call gap with 5 and predict the padding.', 'What does this function return?', 'One spacing value', 'A complete HTML element'),
 L('Build a responsive card', 'Sass can group a screen-size rule with the component it styles. The output is still a normal CSS media query.', 'scss', '.card {\n  padding: 1rem;\n  @media (min-width: 40rem) { padding: 2rem; }\n}', 'The card has 1rem padding on narrow screens and 2rem when the viewport is at least 40rem wide.', 'A media query checks the viewport here, not the card width. Test the built CSS at more than one screen size.', 'Change the wider-screen padding and test both sizes.', 'When does this card use 2rem padding?', 'When the viewport is at least 40rem wide', 'Only when the card contains two paragraphs'),
])

build('web-accessibility',
 'An accessible page can be used in different ways. Some people use a keyboard, a screen reader or larger text. Learn small choices that make words, forms and controls easier for more people to use.',
 'Try runnable HTML here with a keyboard as well as a mouse. A screen reader is a tool that reads page information aloud. Test real pages with people and tools; one automated check cannot prove everything works.',
 'Uses semantic HTML and WCAG 2.2 beginner principles; examples are not a compliance certificate.', [
 L('Use a real button', 'A button already knows how to work with a keyboard. A plain div does not become a button just because it looks like one.', 'html', '<button type="button" onclick="this.textContent=\'Thank you!\'">Say hello</button>', 'The control works with a click, Enter or Space when focused.', 'Do not replace a button with a clickable div unless you also rebuild all the button behaviour. Native HTML is simpler.', 'Reach the button with Tab and activate it with Space.', 'Which element already supports button keyboard behaviour?', 'button', 'div', slug='introduction', runnable=True),
 L('Give the page a clear outline', 'Headings tell readers how a page is organised. A screen reader can list headings to help someone move between topics.', 'html', '<h1>Our school garden</h1><h2>Plants</h2><p>We grow beans.</p><h2>Jobs</h2><h3>Watering</h3><p>Water in the morning.</p>', 'The page has one main title, two main sections and a smaller watering section.', 'Choose heading levels for their place in the outline. Use CSS to change size instead of skipping levels for appearance.', 'Add another h3 job under Jobs.', 'Why use headings in a sensible order?', 'They describe the page structure', 'They automatically translate all words', runnable=True),
 L('Name important page regions', 'Elements such as nav and main name big page regions. These names help reading tools offer shortcuts.', 'html', '<header><p>Garden club</p></header><nav aria-label="Main"><a href="#plants">Plants</a></nav><main id="plants"><h1>Plants</h1><p>Beans grow here.</p></main>', 'The navigation link moves to the plants content. The main element identifies the main region.', 'A page normally has one main region that is not hidden. Do not wrap every small card in main.', 'Find the page region containing the main information.', 'Which element identifies the main content?', 'main', 'span', runnable=True),
 L('Write useful image words', 'Alternative text describes a useful image for someone who cannot see it. Decorative images use an empty alt value.', 'html', '<!-- Replace these paths with real local images in your project. -->\n<img src="bean-plant.jpg" alt="A bean seedling with two green leaves">\n<img src="corner-flower.svg" alt="">', 'A screen reader can describe the seedling and skip the decorative corner flower.', 'Do not use file names as alt text. If an image is a control, describe its action or use a labelled button.', 'Write a short alt description for a photo in your own project.', 'Why does the decorative flower use alt=""?', 'It adds no information that needs to be read', 'It tells the browser to read its file name'),
 L('Label a form field', 'A visible label explains what to type. Matching its for value with an input id links the two parts.', 'html', '<label for="book">Favourite book</label><input id="book" name="book" type="text">', 'Clicking the label focuses the field. A reading tool can announce Favourite book as its name.', 'A placeholder disappears during typing and is not a good replacement for a visible label.', 'Click the label and check which input receives focus.', 'Which two values need to match?', 'The label for and input id', 'The label words and the CSS colour', runnable=True),
 L('Connect help text', 'A field can have a short help message as well as a label. aria-describedby connects the field to that extra explanation.', 'html', '<label for="name">Club name</label><input id="name" aria-describedby="name-help"><p id="name-help">Use the name shown on your club card.</p>', 'A reading tool can announce the field label and then its help text.', 'The described-by value must name an existing id. Do not put the whole help sentence inside the attribute.', 'Change the help text to suit a different form.', 'What belongs in aria-describedby?', 'The id of the help element', 'A random colour name', runnable=True),
 L('Keep keyboard focus clear', 'Focus is the place that will receive the next key action. A visible outline shows that place to someone using a keyboard.', 'html', '<style>button:focus-visible { outline: 3px solid #174a8b; outline-offset: 4px; }</style><button>First choice</button><button>Second choice</button>', 'Using Tab moves a visible focus outline between the buttons.', 'Avoid outline: none unless you provide another equally clear focus mark.', 'Use only the keyboard to move between both buttons.', 'Why is a focus outline useful?', 'It shows where keyboard actions will go', 'It hides controls from screen readers', runnable=True),
 L('Add a skip link', 'A skip link lets a keyboard user move past repeated navigation and straight to the main content.', 'html', '<a href="#main">Skip to main content</a><nav aria-label="Main"><a href="#home">Home</a></nav><main id="main" tabindex="-1"><h1>Today\'s reading</h1><p>Pick a short story.</p></main>', 'The first link takes the reader to the main region. tabindex=-1 lets that region receive focus without joining the normal Tab order.', 'The link target id must exist. Test that focus and scrolling both move as intended.', 'Activate the skip link with Enter.', 'What problem does a skip link help solve?', 'Passing the same navigation on every page', 'Storing passwords in a browser', runnable=True),
 L('Make links explain their destination', 'Link words should make sense when read on their own. Clear words tell a reader where a link will go.', 'html', '<p><a href="#timetable">Read the garden club timetable</a></p><section id="timetable"><h2>Garden club timetable</h2><p>We meet on Friday.</p></section>', 'The link says what it opens and moves to the matching timetable section.', 'Repeated links named Click here give little help when a screen reader lists links alone.', 'Write a clear link label for a list of books.', 'Which link wording is more useful on its own?', 'Read the garden club timetable', 'Click here', runnable=True),
 L('Explain a result in words', 'A polite live region can announce a small update without moving keyboard focus. It is useful for a saved message or a count.', 'html', '<button id="save">Save practice</button><p id="status" role="status"></p><script>document.querySelector("#save").onclick=()=>{document.querySelector("#status").textContent="Practice marked as saved in this example.";};</script>', 'The click adds a status message. A screen reader can announce it when it is ready.', 'Do not use a live region for every changing word. Too many announcements are hard to follow.', 'Change the status message to a short, clear result.', 'Does a status message need to steal focus?', 'No, it can be announced without moving focus', 'Yes, every update must move focus', runnable=True),
 L('Respect less-motion settings', 'Some people feel unwell when a page moves a lot. The reduced-motion setting asks pages to use less movement.', 'html', '<style>.card { transition: transform 200ms; }.card:hover { transform: translateY(-3px); } @media (prefers-reduced-motion: reduce) { .card { transition:none; }.card:hover { transform:none; } }</style><div class="card">Reading card</div>', 'The hover lift is removed when reduced motion is requested by the system.', 'Do not make important information available only through animation. The words should remain understandable without motion.', 'Turn on reduced motion in your system and compare the card.', 'What does prefers-reduced-motion check?', 'The person\'s motion preference', 'The number of pictures on a page', runnable=True),
 L('Check a page in several ways', 'Accessibility testing needs more than one check. Keyboard use, zoom, contrast tools and screen readers each reveal different problems.', 'text', '1. Use Tab and Shift+Tab through the page.\n2. Activate controls with Enter or Space.\n3. Zoom text and page to 200%.\n4. Check labels and error messages.\n5. Run an automated accessibility check.\n6. Try the main task with a screen reader.', 'You get a list of real problems to fix, such as a hidden focus mark or a field with no label.', 'A clean automated report does not prove that every task is easy or understandable. Include manual checks.', 'Check one form using the keyboard and 200% zoom.', 'Can one automated check prove a page has no accessibility problems?', 'No, manual checks are needed too', 'Yes, it proves every task works'),
])

build('responsive-web-design',
 'Responsive design makes a page fit the space available. A phone and a large monitor can show the same useful content in different layouts. Learn flexible boxes, readable text and simple screen rules.',
 'Use the runnable HTML examples here, then resize a local browser page or its device preview. The CSS examples are inside each small page, so no framework is required.',
 'Uses modern CSS Grid, Flexbox, media queries and size container queries.', [
 L('Let the page use the device width', 'A viewport is the area a browser uses to show a page. A viewport meta tag helps mobile browsers use the device width for the layout.', 'html', '<meta name="viewport" content="width=device-width, initial-scale=1"><h1>A page for any screen</h1><p>Start with the space you have.</p>', 'A mobile browser uses the device width instead of a wide pretend desktop page.', 'Do not disable zoom with user-scalable=no. People may need to enlarge the page.', 'Find the viewport meta tag in a complete HTML page.', 'Why keep zoom enabled?', 'Some readers need larger text and controls', 'Zoom prevents all links from working', slug='introduction', runnable=True),
 L('Use a flexible content width', 'A box can use most of the available width while also having a maximum width. This avoids both cramped phones and very long lines.', 'html', '<style>main { width:min(100% - 2rem, 60rem); margin-inline:auto; }</style><main><h1>Reading club</h1><p>This content stays away from the screen edges.</p></main>', 'The main area has side space on narrow screens and stops growing after 60rem.', 'A fixed width such as 1200px can overflow a phone. Use a flexible limit instead.', 'Resize the page and watch the side space.', 'What stops the content getting too wide?', 'The 60rem maximum in min()', 'The number of paragraphs', runnable=True),
 L('Let pictures shrink', 'A responsive image can shrink to fit its parent while keeping its shape. Auto height keeps the original width-to-height ratio.', 'html', '<style>img { max-width:100%; height:auto; }</style><p>In your project, apply this rule to a real image with width and height attributes.</p>', 'Images using this rule stay within their parent width. Their shape is kept instead of being stretched.', 'Do not set an unrelated fixed height and width if that would squash the picture.', 'Apply the rule to a local photo and narrow the window.', 'Why use height:auto with a flexible image width?', 'To keep the picture\'s shape', 'To make every image a square', runnable=True),
 L('Wrap a row of items', 'Flexbox can wrap items onto a new row when there is not enough space. A gap adds space without needing manual margins on every item.', 'html', '<style>.items { display:flex; flex-wrap:wrap; gap:1rem; }.items div { flex:1 1 12rem; padding:1rem; background:#eef4ff; }</style><div class="items"><div>Stories</div><div>Poems</div><div>Science</div></div>', 'The boxes share a row when space allows and wrap when it becomes narrow.', 'Without flex-wrap, items may squeeze too much or overflow. Test long labels too.', 'Add a fourth box and resize the page.', 'What allows a flex row to make another row?', 'flex-wrap: wrap', 'text-align: center', runnable=True),
 L('Make a grid that fits', 'An auto-fit grid chooses how many columns can fit. minmax gives each column a useful minimum and lets it share extra room.', 'html', '<style>.grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,12rem),1fr)); gap:1rem; }.grid div { background:#eef4ff; padding:1rem; }</style><div class="grid"><div>Book A</div><div>Book B</div><div>Book C</div></div>', 'The number of columns changes with the space. Each card can shrink to the full available width on a very narrow screen.', 'A minimum wider than the screen can still overflow. The inner min(100%,12rem) avoids that.', 'Add two more cards and compare narrow and wide views.', 'What does auto-fit decide?', 'How many columns can fit the available space', 'How many letters each card can contain', runnable=True),
 L('Add one larger-screen rule', 'A media query applies styles only when a viewport rule matches. Start with a simple small-screen layout, then add roomier choices.', 'html', '<style>.page { display:grid; gap:1rem; } @media (min-width:48rem) { .page { grid-template-columns:2fr 1fr; } }</style><div class="page"><main><h1>Story</h1><p>Main reading.</p></main><aside>Related books</aside></div>', 'The content stacks below 48rem. Wider screens show a main column and a smaller side column.', 'Choose breakpoints where your content needs them, not only from names of popular devices.', 'Change 48rem and see where the layout switches.', 'Which layout is the starting layout here?', 'One stacked column', 'A permanent fixed-width desktop layout', runnable=True),
 L('Let text grow within limits', 'clamp chooses a value between a minimum and maximum. It can let a heading grow gently as the viewport grows.', 'html', '<style>h1 { font-size:clamp(1.5rem, 1rem + 3vw, 3rem); }</style><h1>Read something new</h1>', 'The heading scales with the viewport but stays between 1.5rem and 3rem.', 'Do not use only viewport units for all text. Keep readable limits and check browser zoom.', 'Compare the heading at a narrow and a wide width.', 'What does clamp provide?', 'A minimum, a preferred value and a maximum', 'A fixed number of words', runnable=True),
 L('Give controls room', 'Touch users need controls that are easy to select. Padding and spacing help keep neighbouring choices apart.', 'html', '<style>button { min-height:44px; padding:.6rem 1rem; } .actions { display:flex; flex-wrap:wrap; gap:.75rem; }</style><div class="actions"><button>Read now</button><button>Save for later</button></div>', 'The two buttons have roomy targets and a clear gap, even when they wrap.', 'A tiny icon with no accessible name is not enough. Keep labels and avoid crowding nearby targets.', 'Test the buttons at a narrow width.', 'Why leave space between touch controls?', 'To reduce accidental taps on the wrong control', 'To stop keyboard users reaching them', runnable=True),
 L('Handle long words', 'Long links or words can force a box wider than its screen. overflow-wrap lets a long piece of text break when needed.', 'html', '<style>.card { max-width:16rem; overflow-wrap:anywhere; padding:1rem; border:1px solid; }</style><div class="card">averylongsamplewordthatwouldotherwiseoverflowthenarrowcard</div>', 'The long word wraps inside the narrow card instead of pushing the layout sideways.', 'Hiding overflow can hide important words. Prefer a wrapping rule when the text needs to be read.', 'Replace the word with a long sample address.', 'What does overflow-wrap help prevent?', 'Long text pushing out of its box', 'Every paragraph having more than one sentence', runnable=True),
 L('Make tables usable on narrow screens', 'A table may need more width than a phone. A named scroll area can keep the table readable without making the whole page scroll sideways.', 'html', '<style>.table-wrap { max-width:100%; overflow-x:auto; } table { min-width:30rem; } th,td { padding:1rem; }</style><div class="table-wrap" tabindex="0" role="region" aria-label="Club timetable"><table><caption>Friday clubs</caption><tr><th>Club</th><th>Room</th><th>Time</th></tr><tr><td>Garden</td><td>School yard</td><td>After lunch</td></tr></table></div>', 'On a narrow screen, only the table region can scroll sideways. Its name explains the region to a reading tool.', 'Keep table headers and the caption. Do not turn a data table into unlabeled boxes just to fit it.', 'Narrow the page and scroll the table with a keyboard.', 'Which part should scroll horizontally here?', 'The table region', 'The entire page and every paragraph', runnable=True),
 L('Respond to a component width', 'A container query checks the size of a chosen parent box. A card can adapt to a narrow sidebar even on a wide screen.', 'html', '<style>.holder { container-type:inline-size; }.card { display:block; } @container (min-width:25rem) { .card { display:flex; gap:1rem; } }</style><div class="holder"><article class="card"><h2>Moon Trip</h2><p>A short space story.</p></article></div>', 'The card switches to a row when its container, not the viewport, is at least 25rem wide.', 'A size container query needs a container-type on an ancestor. It does not measure the element it is changing here.', 'Place the holder in a narrower area and compare the card.', 'What width does this @container rule check?', 'The chosen ancestor container width', 'Always the whole monitor width', runnable=True),
 L('Test real content and zoom', 'A responsive layout needs testing with real words and larger text. A design can fit empty boxes yet fail when a title gets long.', 'text', 'Check a narrow phone-sized width.\nCheck a wide desktop width.\nTry a very long title.\nZoom the page to 200%.\nUse Tab through every control.\nCheck that reading does not need sideways scrolling.', 'You learn which part needs a flexible size, a wrap rule or more space.', 'Do not test only one screenshot size. Content and user settings can change the layout.', 'Test one page with a long title at 200% zoom.', 'Why test a long title?', 'Real content can take more space than a short sample', 'Long titles make CSS stop loading'),
])

build('progressive-web-apps',
 'A progressive web app is a website that can add useful app features. It may offer an install option or an offline page. Learn how a manifest and a service worker help, without assuming every browser behaves the same.',
 'These examples belong in separate files on your own HTTPS or localhost site. Service workers need that trusted origin and cannot run in this site\'s sandbox. Use browser developer tools to inspect them.',
 'Uses the Web App Manifest, Service Worker and Cache Storage standards.', [
 L('Start with a useful website', 'A progressive web app starts as a working website. Extra features should help even when installation or offline support is not available.', 'html', '<!doctype html><html lang="en"><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reading list</title></head><body><main><h1>Reading list</h1><p>Choose a book for today.</p></main></body></html>', 'The page works as a normal website before any app feature is added.', 'Do not hide the main content just because a browser has no install button.', 'Open the basic page before adding a service worker.', 'What should work before PWA extras are added?', 'The normal website', 'Only a push notification service', slug='introduction'),
 L('Describe the app in a manifest', 'A manifest is a JSON file that describes the app name, start address and display choices. A browser can use it when offering installation.', 'json', '{"name":"Reading Club","short_name":"Read","start_url":"/","scope":"/","display":"standalone","background_color":"#ffffff","theme_color":"#174a8b"}', 'Save this as manifest.webmanifest. It supplies app details; a browser may need valid icons and other checks before offering installation.', 'A manifest does not guarantee that every browser will show an install prompt.', 'Choose a short app name that fits under an icon.', 'What kind of file is this manifest?', 'A JSON description of the web app', 'A database of passwords'),
 L('Link the manifest and icons', 'The page must link its manifest. Icons should be real image files in the sizes declared by the manifest.', 'html', '<link rel="manifest" href="/manifest.webmanifest">\n<meta name="theme-color" content="#174a8b">\n<!-- In the manifest, add real 192x192 and 512x512 PNG icons with their actual sizes. -->', 'The browser can discover the manifest from the page. In its app tools, check that the manifest and icons load without errors.', 'Do not list icon files that do not exist. Use actual local images and accurate size values.', 'Check the manifest request in the browser Network panel.', 'How does the page point to its manifest?', 'A link with rel="manifest"', 'An h1 containing the file name'),
 L('Register a service worker', 'A service worker is a script that the browser can run separately from the page. It can handle requests within its scope.', 'javascript', 'if ("serviceWorker" in navigator) {\n  navigator.serviceWorker.register("/sw.js").catch(console.error);\n}', 'On HTTPS or localhost, the browser tries to install sw.js. Put an actual worker file at that path.', 'A worker file normally controls its folder and lower paths. Its location affects its scope.', 'Find the worker scope in browser developer tools.', 'Why check "serviceWorker" in navigator?', 'To see whether this browser supports the feature', 'To create a new user account'),
 L('Install an offline page', 'The install event is a chance to prepare files for later use. waitUntil keeps the install job open while those files are saved.', 'javascript', '// sw.js\nself.addEventListener("install", event => {\n  event.waitUntil(caches.open("reading-v1").then(cache => cache.addAll(["/offline.html"])));\n});', 'The worker stores a real offline.html page in the named cache during installation.', 'Every file in addAll must load successfully. A missing offline.html can make installation fail.', 'Create offline.html with a short offline message.', 'Why call event.waitUntil?', 'To let the browser wait for the cache job', 'To pause the browser forever'),
 L('Give navigation an offline fallback', 'A fetch handler can try the network first and use a saved page when that request fails. Limit the rule to the kind of request you intend to handle.', 'javascript', '// Add to sw.js after the install handler.\nself.addEventListener("fetch", event => {\n  if (event.request.mode === "navigate") {\n    event.respondWith(fetch(event.request).catch(async () => {\n      return await caches.match("/offline.html") || new Response("You are offline.", {headers:{"Content-Type":"text/plain"}});\n    }));\n  }\n});', 'Page navigation uses the network when available. If it fails, a cached offline page or a plain message is returned.', 'A fallback page does not make every page or every data request available offline.', 'Use the browser offline setting and reload a controlled page.', 'When is the offline fallback used here?', 'When a navigation network request fails', 'For every successful network request'),
 L('Choose a cache rule for a purpose', 'Cache-first uses a stored response before trying the network. It suits files whose addresses change when their contents change.', 'javascript', '// Example helper inside sw.js\nasync function cachedAsset(request) {\n  const cache = await caches.open("reading-assets-v1");\n  const saved = await cache.match(request);\n  if (saved) return saved;\n  const response = await fetch(request);\n  if (response.ok) await cache.put(request, response.clone());\n  return response;\n}', 'The helper reuses a stored response. On a first successful fetch, it saves a copy and returns the original response.', 'Use this only for selected safe GET assets. Personal data and frequently changing documents need a deliberate policy.', 'Explain why response.clone is used before storing a copy.', 'Why clone the response before caching it?', 'The cache and caller each need a readable response body', 'Cloning changes the file colour'),
 L('Remove your own old caches', 'The activate event can tidy old cache versions. Use a clear prefix so your worker only removes caches it owns.', 'javascript', 'self.addEventListener("activate", event => {\n  event.waitUntil(caches.keys().then(keys => Promise.all(\n    keys.filter(key => key.startsWith("reading-") && !["reading-v1", "reading-assets-v1"].includes(key)).map(key => caches.delete(key))\n  )));\n});', 'Old reading-prefixed caches are removed. The two current names are kept.', 'Do not delete every cache on the origin. Another app on that origin may own a different cache.', 'Identify which cache names this filter would keep.', 'Why use a reading- prefix check?', 'To avoid deleting caches owned by another app', 'To delete all browser history'),
 L('Understand a waiting update', 'A new worker may wait while the old one still controls open pages. This avoids mixing a new app version with an old page halfway through a task.', 'javascript', 'navigator.serviceWorker.ready.then(registration => {\n  console.log("Active worker:", registration.active?.scriptURL);\n  console.log("Waiting worker:", registration.waiting?.scriptURL);\n});', 'The console shows the active worker and, when present, a waiting version. The values depend on the current installation state.', 'Do not force an update and reload in the middle of unsaved work. Offer a clear update action when needed.', 'Inspect active and waiting workers after changing sw.js.', 'Why can an installed worker be waiting?', 'An older version still controls open pages', 'Its file must be named wait.js'),
 L('Save a small local preference', 'A page can remember a small choice in localStorage. This storage belongs to that browser and origin, not to a cloud account.', 'javascript', 'try {\n  localStorage.setItem("reading-theme", "dark");\n  console.log(localStorage.getItem("reading-theme"));\n} catch {\n  console.log("This browser could not save the choice.");\n}', 'On a page where storage is allowed, the console shows dark. The catch handles blocked or unavailable storage.', 'Service workers do not have localStorage. Use it in page code, and never assume browser data is permanent.', 'Change the theme value and read it back.', 'Where is this choice stored?', 'In this browser for this site', 'Automatically on every device'),
 L('Treat network hints as hints', 'The online and offline events are useful clues. A device can report online even when a particular server cannot be reached.', 'javascript', 'window.addEventListener("offline", () => console.log("The browser reports offline."));\nwindow.addEventListener("online", () => console.log("The browser reports online. Try the request again."));', 'The page can explain a change in connection state. It still needs to catch failures from each real request.', 'Do not treat navigator.onLine as proof that every request will succeed.', 'Compare an offline event with a failed request.', 'Does an online event guarantee that a server can be reached?', 'No, the actual request can still fail', 'Yes, every server must be available'),
 L('Test and reset your practice app', 'A PWA needs tests for first visit, repeat visit, offline use and updates. Old workers and caches can hide mistakes during development.', 'text', 'Open Application tools on your own local project.\nCheck manifest errors and worker scope.\nLoad once online, then test offline navigation.\nChange sw.js and inspect the waiting version.\nFor a clean test, unregister only your practice worker and clear only its app caches.', 'These checks show whether the fallback, scope and update behaviour match your design.', 'Do not clear unrelated site data. A clean local test and a real returning visit are different tests.', 'Test the offline page after one successful online visit.', 'Why test a first visit separately from a repeat visit?', 'The first visit may have no saved files yet', 'Repeat visits never use a network'),
])

build('web-apis',
 'A web API is a set of tools the browser offers to JavaScript. Some tools work with text, files or page size. Others ask for permission. Learn a small useful job for each tool and handle cases where it cannot work.',
 'Use these examples in a local page in a current browser. APIs involving files, storage, clipboard or location may need HTTPS, a user action or permission. They are shown as code because this site\'s sandbox limits those features.',
 'Uses standard browser APIs with feature checks and local sample data.', [
 L('Read JSON text', 'JSON is a text format for data. JSON.parse turns that text into JavaScript values that code can read.', 'javascript', 'const book = JSON.parse(\'{"title":"Moon Trip","pages":60}\');\nconsole.log(book.title);', 'The console shows Moon Trip.', 'JSON text uses double quotes around property names. Invalid JSON throws an error that real input code should catch.', 'Change the title in the JSON text and read it again.', 'What does JSON.parse produce?', 'JavaScript values from JSON text', 'A picture of the text', slug='introduction'),
 L('Fetch local data', 'fetch asks for a resource and returns a promise for a response. A successful connection can still return a status such as 404, so check ok.', 'javascript', 'async function readBooks() {\n  const response = await fetch("/books.json");\n  if (!response.ok) throw new Error("Could not load books");\n  return response.json();\n}\nreadBooks().then(console.log).catch(console.error);', 'With a real books.json file at that address, the code prints its parsed data. Missing files produce a handled error.', 'Create the local JSON file first. fetch does not reject automatically for every HTTP error status.', 'Write a local books.json with a two-item array.', 'Why check response.ok?', 'A response can arrive with an error status', 'It changes JSON into HTML'),
 L('Stop a request', 'AbortController gives a request a stop signal. It is useful when a page no longer needs a slow answer.', 'javascript', 'const controller = new AbortController();\nfetch("/books.json", {signal: controller.signal})\n  .then(response => response.text()).then(console.log)\n  .catch(error => console.log(error.name));\ncontroller.abort();', 'The request is cancelled if it is still in progress. Its rejection is handled, usually with the name AbortError.', 'Cancelling a request does not undo work a server has already done. It stops waiting or reading on the client side.', 'Find the signal passed into fetch.', 'Which object sends the stop signal?', 'AbortController', 'JSON.parse'),
 L('Use URL search values', 'URLSearchParams reads and writes query values in an address. It handles the encoding of spaces and special characters.', 'javascript', 'const params = new URLSearchParams("topic=space&level=1");\nparams.set("topic", "garden club");\nconsole.log(params.get("topic"));\nconsole.log(params.toString());', 'The first line is garden club. The query string contains topic=garden+club and level=1.', 'Use the API rather than joining raw user text into a URL by hand.', 'Add a page value of 2 to the search parameters.', 'What does params.get("topic") return?', 'The decoded topic text', 'The whole page HTML'),
 L('Remember a small browser value', 'localStorage stores small text values for one site in one browser. Objects need to be turned into text first.', 'javascript', 'try {\n  localStorage.setItem("club-books", JSON.stringify(["Moon Trip"]));\n  const books = JSON.parse(localStorage.getItem("club-books") || "[]");\n  console.log(books.length);\n} catch { console.log("Storage is unavailable."); }', 'The console shows 1 where storage is allowed. Otherwise the page gives a handled message.', 'Browser storage can be cleared or blocked. Do not use it as the only copy of important work.', 'Store a second title and check the length.', 'Why use JSON.stringify before storing the array?', 'localStorage stores text values', 'It uploads the array to a server'),
 L('Read a chosen file', 'A file input lets a person choose a file. The page can read that chosen file; it cannot freely browse every file on the computer.', 'html', '<label for="file">Choose a text file</label><input id="file" type="file" accept="text/plain"><pre id="text"></pre><script>document.querySelector("#file").onchange=async e=>{const file=e.target.files[0];if(file)document.querySelector("#text").textContent=await file.text();};</script>', 'After a text file is chosen, its words appear in the pre element.', 'Use textContent for the file contents. A file may contain text that should never be treated as HTML.', 'Try a small text file that you created yourself.', 'Which file can this page read through the input?', 'The file the person chose', 'Every private file on the computer'),
 L('Copy text after a click', 'The Clipboard API can write text to the clipboard. It normally needs a secure page and a deliberate user action.', 'html', '<button id="copy">Copy club name</button><p id="status"></p><script>document.querySelector("#copy").onclick=async()=>{try{await navigator.clipboard.writeText("Garden club");document.querySelector("#status").textContent="Copied";}catch{document.querySelector("#status").textContent="Please copy the name by hand.";}};</script>', 'On an allowed HTTPS or localhost page, the button copies Garden club. A failure shows a manual-copy message.', 'Clipboard support and permission vary. Keep a useful fallback.', 'Change the copied words to a different club name.', 'Why run the copy step from a button action?', 'Clipboard access may need a user gesture', 'A button makes text secret'),
 L('Ask for a location carefully', 'Geolocation asks the browser for a location. The person can refuse, and the answer may be approximate.', 'javascript', 'if ("geolocation" in navigator) {\n  navigator.geolocation.getCurrentPosition(\n    position => console.log("Accuracy in metres:", position.coords.accuracy),\n    () => console.log("You can choose a place by hand instead."),\n    {timeout: 5000}\n  );\n}', 'When used after an appropriate user action on a secure page, it reports accuracy or a handled failure.', 'Explain why location is useful before asking. Do not require it for a task that can work with a manual choice.', 'Describe a manual alternative when permission is refused.', 'Can the person refuse a location request?', 'Yes, the page must handle that choice', 'No, every page always gets it'),
 L('Draw a simple canvas shape', 'Canvas is a drawing area controlled by JavaScript. Its 2D context has commands for shapes and text.', 'html', '<canvas id="art" width="240" height="120" aria-label="A blue rectangle">A blue rectangle</canvas><script>const ctx=document.querySelector("#art").getContext("2d");ctx.fillStyle="navy";ctx.fillRect(20,20,100,60);</script>', 'A navy rectangle is drawn 20 units from the left and top, with a width of 100 and height of 60.', 'Canvas pixels do not provide the same readable structure as normal HTML. Give useful text for important information.', 'Change the rectangle width and colour.', 'Which command draws the filled rectangle?', 'fillRect', 'querySelectorAll'),
 L('Watch when a part comes into view', 'IntersectionObserver tells your code when an element crosses a visibility boundary. It avoids doing a manual scroll check on every scroll event.', 'html', '<div style="height:600px">Scroll down</div><p id="target">You found the note.</p><script>const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){console.log("Note entered view");observer.unobserve(entry.target);}}});observer.observe(document.querySelector("#target"));</script>', 'When the note enters the viewport, the message is logged once and the observer stops watching it.', 'An intersection is not proof that a person read the content. It only reports a geometric visibility condition.', 'Move the target farther down and try again.', 'Why call unobserve after the first message?', 'Only one notification is needed in this example', 'It deletes the paragraph'),
 L('Watch a box size', 'ResizeObserver reports changes to an element\'s size. This can help a chart fit its own box rather than the whole screen.', 'html', '<div id="box" style="width:60%;padding:1rem;border:1px solid">A flexible box</div><script>const observer=new ResizeObserver(entries=>{console.log(Math.round(entries[0].contentRect.width));});observer.observe(document.querySelector("#box"));</script>', 'The console logs the content width when the box is first observed and when that size changes.', 'Avoid changing the observed size in a way that creates an endless resize loop.', 'Resize the window and compare the reported widths.', 'What does this observer measure?', 'The selected box\'s size', 'The number of files on disk'),
 L('Move a calculation to a worker', 'A web worker runs JavaScript in another thread. It can do a calculation without directly changing the page DOM.', 'javascript', '// worker.js\nself.onmessage = event => { self.postMessage(event.data * 2); };\n\n// main.js, a separate file on the same local site\nconst worker = new Worker("./worker.js");\nworker.onmessage = event => { console.log(event.data); worker.terminate(); };\nworker.postMessage(6);', 'With the two real files served locally, the main page logs 12 and then stops the worker.', 'Save the two sections as separate files. A worker cannot use document.querySelector to change the page.', 'Send 9 to the worker and predict its reply.', 'How does the worker send its answer?', 'With postMessage', 'By directly editing a paragraph'),
])

build('web-performance',
 'A fast page lets people read and act without a long wait. Performance work starts with measuring a real task. Learn how images, scripts, styles and layout choices affect the way a page feels.',
 'Use a local test page and browser developer tools. Code samples show a page choice or a measurement. Compare before and after under the same conditions; exact timings depend on the device and network.',
 'Uses current Core Web Vitals concepts: LCP, INP and CLS, plus standard browser tools.', [
 L('Measure before changing code', 'A performance measurement is a clue about a real task. A slow phone and a fast laptop may get different results from the same page.', 'text', 'Choose one page and one task.\nRecord the device and network setting.\nLoad it several times.\nWrite down what feels slow.\nChange one cause and repeat the same test.', 'A fair comparison can show whether a change helped that task instead of only changing a number by chance.', 'Do not compare one fast cached visit with one slow first visit and call it a fair test.', 'Choose one page action you want to measure.', 'Why keep test conditions the same?', 'So before-and-after results can be compared fairly', 'So every result is guaranteed to be zero', slug='introduction'),
 L('Know the three web vital ideas', 'Core Web Vitals describe loading, response to input and visual stability. Their short names are LCP, INP and CLS.', 'text', 'LCP: When the largest main content becomes visible.\nINP: How quickly the page shows a response to interactions.\nCLS: How much visible content unexpectedly moves.', 'The three measures help separate a slow load, a slow click response and a jumping layout.', 'A single lab run is not the same as measurements from many real visits. Use each kind of evidence for its purpose.', 'Match a jumping button to the measure that tracks movement.', 'Which measure is about unexpected layout movement?', 'CLS', 'LCP'),
 L('Give images their size', 'Image width and height tell the browser the picture\'s shape before it finishes loading. That lets the browser keep the right amount of space.', 'html', '<!-- Use the real dimensions of your own image. -->\n<img src="garden.jpg" alt="Our school garden" width="1200" height="800" style="max-width:100%;height:auto">', 'The browser can reserve a 3-to-2 shaped area before garden.jpg loads.', 'Use the real aspect ratio. Wrong dimensions can make the space change again when styles or content arrive.', 'Find the width and height of a local photo.', 'Why declare image width and height?', 'To reserve space and reduce layout jumps', 'To force every image to download twice'),
 L('Load lower images later', 'Lazy loading delays some images until they are near the visible area. This can save early work for a long page.', 'html', '<!-- Place well below the first screen of content. -->\n<img src="club-trip.jpg" alt="The club visits a garden" width="800" height="600" loading="lazy">', 'The browser may wait to load this lower image until the reader gets closer to it.', 'Do not lazy-load the main image people need immediately at the top of the page.', 'Choose which pictures on a long page are safe to delay.', 'Which image is usually a poor lazy-loading choice?', 'The main image visible immediately on page load', 'A photo far below the first screen'),
 L('Offer an image that fits', 'Responsive image sources let the browser choose a suitable image size. A small screen should not always need the largest file.', 'html', '<img src="garden-800.jpg" srcset="garden-400.jpg 400w, garden-800.jpg 800w" sizes="(max-width:600px) 100vw, 600px" width="800" height="600" alt="Garden beds">', 'With real image files at those widths, the browser chooses a source using the layout size and display density.', 'The widths in srcset must match the real files. The sizes hint should match the actual layout.', 'Compare the chosen image request at two viewport sizes.', 'What does srcset offer the browser?', 'Image file choices with their sizes', 'A list of text colours'),
 L('Keep early scripts from blocking HTML', 'A deferred classic script downloads while HTML is read and runs after parsing. This can let the browser build the page sooner.', 'html', '<script src="club.js" defer></script>', 'The browser fetches club.js without stopping HTML parsing at this tag. It executes after the document is parsed.', 'Use a real external script file. defer does not have this effect on an inline classic script.', 'Check the script request in the Network panel.', 'What does defer allow during the download?', 'HTML parsing can continue', 'Every script runs before any HTML exists'),
 L('Load optional code when needed', 'Dynamic import can load a JavaScript module when a feature is used. It can keep optional work out of the first page load.', 'javascript', 'document.querySelector("#chart-button").addEventListener("click", async () => {\n  const { showChart } = await import("./chart.js");\n  showChart();\n});', 'On a page with a real button and chart.js export, the chart module is requested when the feature is first opened.', 'Handle loading errors in a real app. Do not split tiny files blindly if extra requests make the experience worse.', 'Identify a large optional feature in a sample app.', 'When is chart.js first requested here?', 'When the button is clicked', 'Only when the user closes the page'),
 L('Avoid repeating layout work', 'Reading layout after each style change can make the browser repeatedly calculate positions. Group reads and then writes when possible.', 'javascript', 'const cards = [...document.querySelectorAll(".card")];\nconst widths = cards.map(card => card.getBoundingClientRect().width);\ncards.forEach((card, index) => { card.style.minHeight = widths[index] / 2 + "px"; });', 'The code reads all widths first, then applies the new heights.', 'Do not assume every DOM read is expensive. Measure the real loop before making complicated changes.', 'Find the read phase and the write phase in this code.', 'Why group the width reads before style writes?', 'To avoid unnecessary repeated layout calculations', 'To stop all CSS from loading'),
 L('Schedule a visual update', 'requestAnimationFrame asks the browser to run a visual update before a future paint. It is useful when combining several changes for one frame.', 'javascript', 'const box = document.querySelector(".box");\nrequestAnimationFrame(() => {\n  box.style.transform = "translateX(20px)";\n});', 'On a page with a .box element, the box moves in a scheduled visual update.', 'This is not a timer for exact wall-clock work. Background tabs may pause or slow animation frames.', 'Change the movement distance and observe the box.', 'What kind of job suits requestAnimationFrame?', 'A page visual update', 'A guarantee to run every exact millisecond'),
 L('Use a font fallback', 'A fallback font shows readable words while a web font loads. font-display: swap lets text appear using that fallback.', 'css', '@font-face {\n  font-family: "ClubText";\n  src: url("/fonts/club.woff2") format("woff2");\n  font-display: swap;\n}\nbody { font-family: "ClubText", system-ui, sans-serif; }', 'With a real font file, text can appear in a system font first and switch when ClubText is ready.', 'Different font shapes can still move text. Choose a similar fallback and measure the page shift.', 'Test the page with a slow font request.', 'What does the fallback font help avoid?', 'Invisible words while the custom font loads', 'Every kind of network request'),
 L('Understand browser caching', 'A cache keeps a response so it may be reused. Cache headers tell the browser how long a response can stay fresh.', 'text', 'For a versioned asset such as app.a1b2c3.js, a static host may send:\nCache-Control: public, max-age=31536000, immutable\n\nFor HTML that changes, use a policy that lets the browser check for updates.', 'A file whose address changes with its contents can be cached for a long time. HTML needs a policy that still delivers updates.', 'Do not give changing files the same long-lived immutable address. These are host response headers, not HTML tags.', 'Explain why a changed asset should get a new versioned name.', 'Why are long cache times useful for versioned assets?', 'The address changes when the contents change', 'The browser can never reuse them'),
 L('Keep a performance checklist', 'A useful performance budget sets limits that matter for the page. Recheck after changes so a fast page does not slowly become heavy.', 'text', 'List important pages and tasks.\nTrack total transferred image and script sizes.\nCheck a slower device and network.\nReview LCP, INP and CLS evidence.\nKeep accessibility and readable content in every check.\nRepeat after large new features.', 'The project gets a repeatable check, not a one-time speed score.', 'Do not remove useful labels, error messages or accessible controls to make a benchmark smaller.', 'Choose one size or timing to track for your project.', 'What makes a performance check useful over time?', 'Repeating it under clear conditions after changes', 'Running it once and never looking again'),
])

build('less',
 'Less is a way to write CSS with shared names, small recipes and calculations. A tool turns it into normal CSS. Learn by styling small boxes and checking the CSS that the tool makes.',
 'Use Less 4 on your computer. Install Node.js first. Save examples as lesson.less, then run npx lessc lesson.less lesson.css. The browser loads lesson.css; this site does not build Less.',
 'Uses Less 4 syntax and the lessc command-line compiler.', [
 L('Build your first Less file', 'Less is a CSS helper language. A compiler translates its extra features into the CSS that browsers already understand.', 'bash', 'npm install --save-dev less@4\nnpx lessc --version', 'Less is added to the project. The version command confirms that the tool can run.', 'Installing the tool does not add styles to a page. You must build a CSS file and link that file from HTML.', 'Check that lessc can print its version.', 'What is the job of lessc?', 'Turn Less into CSS', 'Turn HTML into a database', slug='introduction'),
 L('Store a colour in a name', 'Less variables start with @. A variable lets you reuse a value such as a colour or a spacing size.', 'less', '@ink: navy;\nh1 { color: @ink; }\np { color: @ink; }', 'Both rules have navy as their text colour after compilation.', 'The @ in a variable is not part of the CSS property name. Write color: @ink, not @color: ink.', 'Change ink to teal and build the file again.', 'Which name is a Less variable?', '@ink', '.ink'),
 L('Nest child styles', 'A nested selector chooses an element inside another element. Less combines the outer and inner selectors for you.', 'less', '.card {\n  padding: 12px;\n  p { margin: 0; }\n}', 'The built CSS contains a .card p rule. It removes margins from paragraphs inside cards.', 'A nested p does not style every paragraph. Avoid many layers of nesting.', 'Add a nested h2 rule with a navy colour.', 'What does .card p choose?', 'A paragraph inside a card', 'Only a paragraph outside a card'),
 L('Style the current element', 'The & sign repeats the parent selector. It helps add a state to the same element rather than choosing one of its children.', 'less', '.button {\n  &:hover { background: gold; }\n  &:focus-visible { outline: 3px solid navy; }\n}', 'The CSS contains .button:hover and .button:focus-visible rules for the button itself.', 'A hover style is not enough for keyboard users. Keep a visible focus style too.', 'Choose a new outline colour that is easy to see.', 'What element does &:focus-visible style here?', 'The button itself when it has visible focus', 'Every child inside the button'),
 L('Reuse a mixin', 'A mixin is a group of style choices you can insert into another rule. Empty parentheses keep the recipe from making its own CSS class.', 'less', '.soft-box() { padding: 12px; border-radius: 8px; }\n.card { .soft-box(); }\n.tip { .soft-box(); }', 'Both card and tip get the two style choices. No separate soft-box rule is needed.', 'Call the mixin inside a selector rule. Defining the recipe alone does not style a page part.', 'Use soft-box in a third rule called message.', 'Why use .soft-box() in both rules?', 'To share the same style recipe', 'To create a JavaScript function'),
 L('Pass a mixin value', 'A mixin can accept a value, so one recipe makes several kinds of frame. A default is used when you leave the input empty.', 'less', '.frame(@colour: navy) { border: 2px solid @colour; }\n.book { .frame(); }\n.game { .frame(green); }', 'The book has a navy border and the game has a green border.', 'Use parentheses around the input. Write a colour value rather than a quoted CSS class name.', 'Give game an orange border.', 'Which colour is used by .frame() without an input?', 'navy', 'green'),
 L('Calculate space', 'Less can calculate a size from other sizes. Parentheses make the calculation clear, especially when dividing.', 'less', '@space: 24px;\n.card { padding: (@space / 2); margin: (@space + 4px); }', 'The result uses 12px padding and 28px margin.', 'Keep units compatible. Adding a time in seconds to a length in pixels does not make a useful CSS size.', 'Change space to 20px and calculate both results.', 'What padding comes from 24px divided by 2?', '12px', '48px'),
 L('Split a style file', 'An import brings another Less file into the build. This helps keep shared choices separate from the styles that use them.', 'less', '// colours.less\n@ink: navy;\n\n// lesson.less, saved separately\n@import "colours.less";\nh1 { color: @ink; }', 'With both files in one folder, the built h1 rule uses navy.', 'Save the labelled sections as separate files. A misspelled file path will stop the build.', 'Add a second variable to colours.less and use it.', 'What does @import load in this example?', 'The shared colours.less file', 'A picture from the page'),
 L('Guard a recipe', 'A guard is a rule that decides whether a mixin should run. It can choose a style based on an input number.', 'less', '.label(@size) when (@size >= 20px) { font-weight: bold; }\nh1 { .label(24px); }', 'The h1 rule gets a bold weight because 24px is at least 20px.', 'A guarded mixin may output nothing when its test is false. Check the built CSS when a style is missing.', 'Call the mixin with 16px and check what is output.', 'Why does the 24px call get bold text?', 'It meets the guard rule', 'Every guard is always true'),
 L('Change a colour value', 'Less has colour functions. A function takes a colour and calculates another colour from it.', 'less', '@base: #336699;\n.card { background: lighten(@base, 20%); color: darken(@base, 20%); }', 'The background uses a lighter version of the base colour. The text uses a darker version.', 'A colour calculation does not guarantee readable contrast. Check the result with a contrast tool.', 'Try a smaller lighten amount and compare the colour.', 'What does lighten do?', 'Calculates a lighter colour', 'Makes the HTML file smaller'),
 L('Insert a name into a selector', 'Interpolation puts a variable value inside a selector name. It can make a named theme class.', 'less', '@theme: garden;\n.@{theme}-card { border: 2px solid green; }', 'The output selector is .garden-card. It has a green border.', 'Use @{name} inside the selector text. Plain @name is used for a whole property value.', 'Change the theme name to ocean.', 'What class name does the example create?', '.garden-card', '.theme-card'),
 L('Combine a card and a screen rule', 'A media query chooses styles for certain screen sizes. Less can place it inside the component rule and build normal CSS.', 'less', '.card {\n  padding: 12px;\n  @media (min-width: 640px) { padding: 24px; }\n}', 'Cards get more inner space when the viewport is 640px wide or wider.', 'Test the final CSS in the browser. Less does not choose a screen size while compiling.', 'Set the larger padding to 20px and check both layouts.', 'Who checks the media query screen size?', 'The browser when it displays the page', 'Less only during installation'),
])

build('tailwind-css',
 'Tailwind CSS gives small classes one clear style job. You combine the classes to make a page. Start with colours and space, then build cards that fit both narrow and wide screens.',
 'These examples use Tailwind CSS 4 in a separate project. Install tailwindcss and @tailwindcss/cli. Put @import "tailwindcss"; in input.css and build with npx @tailwindcss/cli -i input.css -o output.css. Link output.css in HTML.',
 'Targets Tailwind CSS 4 and its CSS-first theme setup.', [
 L('Meet utility classes', 'A utility class has one small style job. In Tailwind, you combine these small choices directly on an HTML element.', 'html', '<p class="text-blue-800 font-bold">Our reading club</p>', 'With Tailwind output.css loaded, the words appear bold and dark blue.', 'These class names need built Tailwind CSS. The plain HTML playground does not include it.', 'Find the class that changes the text weight.', 'What does font-bold change?', 'How thick the letters look', 'The words in the paragraph', slug='introduction'),
 L('Add inner and outer space', 'Padding is space inside a box. Margin is space outside a box. Tailwind uses short names for both.', 'html', '<div class="p-4 mb-6 border">Bring a notebook.</div>', 'The box has inner padding, a border and extra space below its outside edge.', 'The number in p-4 is a step on the spacing scale, not four pixels.', 'Change p-4 to p-8 and compare the inner space.', 'Which class adds space inside the box?', 'p-4', 'mb-6'),
 L('Choose readable text', 'Text size and line spacing work together. A paragraph is easier to read when the lines are not squeezed together.', 'html', '<h1 class="text-3xl font-bold">Garden club</h1>\n<p class="text-base leading-7">We plant seeds and watch them grow.</p>', 'The heading is large and bold. The paragraph has a normal text size with roomy lines.', 'Do not choose a heading level only for its appearance. Use HTML heading order for meaning.', 'Try leading-8 for the paragraph and compare it.', 'What does leading-7 control?', 'The height of each text line', 'The number of paragraphs'),
 L('Use colour and borders', 'A background fills a box, while a border marks its edge. Text needs enough contrast against its background.', 'html', '<aside class="bg-yellow-100 text-yellow-950 border border-yellow-400 rounded-lg p-4">\n  Bring water for the plants.\n</aside>', 'The note has a pale yellow background, dark words, a yellow border and rounded corners.', 'Colour alone should not explain a message. Keep the actual reminder in words.', 'Change the border from rounded-lg to rounded-none.', 'Which class gives the box round corners?', 'rounded-lg', 'text-yellow-950'),
 L('Line up a row with flex', 'Flex layout places child boxes in a row by default. You can centre them vertically and give them a gap.', 'html', '<div class="flex items-center gap-3">\n  <span>Books read</span>\n  <strong>4</strong>\n</div>', 'The label and count sit in a row, aligned through the middle, with space between them.', 'items-center aligns across the row. It does not put all the items into the centre of the page.', 'Add one more span and watch how the row changes.', 'Which class adds space between these flex items?', 'gap-3', 'items-center'),
 L('Make grid columns', 'A grid can arrange boxes in rows and columns. The number in grid-cols tells Tailwind how many equal columns to create.', 'html', '<div class="grid grid-cols-2 gap-4">\n  <div>Story books</div><div>Science books</div>\n  <div>Poems</div><div>Maps</div>\n</div>', 'Four items form two rows with two columns each.', 'Add grid as well as grid-cols-2. The column setting needs a grid layout to act on.', 'Change grid-cols-2 to grid-cols-4.', 'How many columns does grid-cols-2 create?', 'Two equal columns', 'Two rows and any number of columns'),
 L('Start small then grow', 'A responsive prefix applies a class from a chosen screen width upwards. Unprefixed classes are the starting rules for all widths.', 'html', '<div class="grid grid-cols-1 gap-4 md:grid-cols-2">\n  <article>First book</article><article>Second book</article>\n</div>', 'The books stack at small widths. At the default md breakpoint and above, they form two columns.', 'md means a minimum width here. It does not mean only one exact device or screen size.', 'Resize the page and find where the second column appears.', 'Which layout is used below md?', 'One column', 'Two columns'),
 L('Show keyboard focus', 'A state prefix changes a style when an element is in that state. focus-visible is useful for a clear keyboard focus mark.', 'html', '<button class="rounded bg-blue-800 px-4 py-2 text-white hover:bg-blue-900 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-blue-800">\n  Read a story\n</button>', 'The button darkens on hover and shows a visible outline during keyboard focus.', 'Do not remove focus outlines without a clear replacement. A keyboard user needs to see the current control.', 'Use Tab to move focus onto the button.', 'Why add focus-visible classes?', 'To show which control the keyboard is using', 'To hide the button from keyboards'),
 L('Use the dark variant', 'The dark variant supplies styles for a dark colour setting. Tailwind 4 uses the system colour preference by default.', 'html', '<article class="bg-white text-slate-900 dark:bg-slate-900 dark:text-white p-4">\n  Evening reading\n</article>', 'The card uses light colours normally and dark colours when the system prefers a dark theme.', 'Changing only the background can make the words hard to read. Choose text colours for both themes.', 'Preview the card in light and dark system modes.', 'Why are both background and text classes changed?', 'To keep the words readable in both themes', 'Because dark mode removes all text'),
 L('Name a theme colour', 'A theme variable adds a design choice that Tailwind can turn into utilities. The --color prefix creates colour utilities.', 'css', '@import "tailwindcss";\n@theme {\n  --color-leaf: #175c3a;\n}\n/* HTML can now use bg-leaf or text-leaf. */', 'After rebuilding, classes such as bg-leaf use the new green colour.', 'Define theme values in the CSS input file. Putting @theme in an HTML class attribute will not work.', 'Add a second named colour to the theme.', 'Which utility can use --color-leaf?', 'bg-leaf', 'theme-leaf-file'),
 L('Keep class names complete', 'Tailwind finds class names by reading your source files as text. Complete class names let it discover the styles you need.', 'javascript', 'const colours = {\n  success: "bg-green-100 text-green-950",\n  warning: "bg-yellow-100 text-yellow-950"\n};\nconst noteClass = colours.success;', 'Both complete class strings can be discovered during a Tailwind build. The selected value is the success string.', 'Do not build a class such as bg-${colour}-100 from pieces and expect the scanner to guess every possible result.', 'Add a complete class string for an information message.', 'Which approach lets Tailwind see each full class?', 'A map of complete class strings', 'Joining unknown colour pieces only at runtime'),
 L('Put a card together', 'A small card combines several single-job classes. Each class still has one job: space, border, text size or layout.', 'html', '<article class="max-w-sm rounded-xl border border-slate-300 p-6 shadow-sm">\n  <h2 class="text-xl font-bold">Book of the week</h2>\n  <p class="mt-2 leading-7">A story about a moon garden.</p>\n  <a class="mt-4 inline-block text-blue-800 underline" href="/books">See the book list</a>\n</article>', 'The card has a limited width, round border, inner space and an underlined link. The /books address must exist in your own site.', 'A good-looking link still needs a real destination. Replace /books with a route your project provides.', 'Change the card text to describe one of your hobbies.', 'What does max-w-sm limit?', 'The maximum width of the card', 'The maximum number of words'),
])

build('javascript-dom',
 'The DOM is the browser\'s model of a page. JavaScript can use it to find a part, change words or react to a click. Learn with small pages that each do one clear job.',
 'The HTML examples are complete small page parts. Use this site\'s HTML Run button. Put the script after the elements it uses so those elements already exist.',
 'Uses standard DOM APIs in current browsers; no framework or account is needed.', [
 L('Find a page element', 'The DOM gives JavaScript a way to work with the parts of a page. querySelector finds the first element that matches a CSS selector.', 'html', '<h1 id="title">Reading club</h1>\n<script>\n  const title = document.querySelector("#title");\n  console.log(title.textContent);\n</script>', 'The heading stays on the page. The console shows Reading club.', 'querySelector can return null if no element matches. Check your id spelling and script position.', 'Change the heading words and read the console again.', 'What does #title choose?', 'The element with id title', 'Every element named title', slug='introduction', runnable=True),
 L('Change words safely', 'textContent replaces the text inside an element. It treats new content as words rather than reading it as HTML markup.', 'html', '<p id="message">Waiting</p>\n<script>\n  document.querySelector("#message").textContent = "Welcome, Mia!";\n</script>', 'The paragraph changes from Waiting to Welcome, Mia!.', 'Use textContent for ordinary user text. Inserting untrusted strings as HTML can make unwanted page parts run.', 'Replace Mia with a different name.', 'What does textContent set?', 'Plain text inside the element', 'A CSS stylesheet', runnable=True),
 L('Choose several elements', 'querySelectorAll gives a list of all matches. You can use forEach to do a small job for every element in that list.', 'html', '<ul><li>Seeds</li><li>Water</li></ul>\n<script>\n  document.querySelectorAll("li").forEach((item) => {\n    item.textContent = "Pack: " + item.textContent;\n  });\n</script>', 'The list shows Pack: Seeds and Pack: Water.', 'The returned list is a snapshot. New elements added later are not automatically added to that same list.', 'Add a third li before the script and run the page.', 'How many matching items does querySelectorAll choose?', 'All current matches', 'Only the first match', runnable=True),
 L('Change a class', 'classList changes class names on an element. CSS can then control what that class looks like.', 'html', '<style>.bright { background: gold; }</style>\n<p id="note">Bring a book.</p>\n<script>\n  document.querySelector("#note").classList.add("bright");\n</script>', 'The paragraph gets the bright class, so its background becomes gold.', 'Pass bright without a dot to classList.add. The dot is only part of a CSS selector.', 'Use classList.remove after add and predict the result.', 'What should classList.add receive?', 'The class name bright without a dot', 'The selector .bright with its dot', runnable=True),
 L('React to a click', 'An event listener is a function that runs when an event happens. A click listener can change a page after a button is pressed.', 'html', '<button id="hello">Say hello</button><p id="reply"></p>\n<script>\n  document.querySelector("#hello").addEventListener("click", () => {\n    document.querySelector("#reply").textContent = "Hello, reader!";\n  });\n</script>', 'Clicking the button puts Hello, reader! in the paragraph.', 'Pass a function to addEventListener. Do not call it immediately when you mean to wait for a click.', 'Change the reply to a greeting for your club.', 'When does the listener run?', 'When the button receives a click', 'Only when the CSS file loads', runnable=True),
 L('Read a form value', 'An input value is the text currently typed into a field. The submit event lets one handler work for a button click or the Enter key.', 'html', '<form id="form"><label for="name">Name</label><input id="name"><button>Greet</button></form><p id="reply"></p>\n<script>\n  document.querySelector("#form").addEventListener("submit", (event) => {\n    event.preventDefault();\n    document.querySelector("#reply").textContent = "Hi, " + document.querySelector("#name").value;\n  });\n</script>', 'Typing Mia and submitting shows Hi, Mia without loading a new page.', 'Use value for an input, not textContent. Keep the label linked with the input id.', 'Submit once by clicking and once with the Enter key.', 'Where is the input\'s current typed text?', 'Its value property', 'Its tag name', runnable=True),
 L('Create a new element', 'createElement makes a new page part. append puts that part inside an existing element.', 'html', '<ul id="books"></ul>\n<script>\n  const item = document.createElement("li");\n  item.textContent = "Moon Trip";\n  document.querySelector("#books").append(item);\n</script>', 'The empty list gains one item named Moon Trip.', 'Creating an element does not show it yet. Add it to a visible part of the document.', 'Create and append a second book item.', 'Which step puts the new item on the page?', 'Appending it to the list', 'Only choosing its JavaScript variable name', runnable=True),
 L('Remove a page part', 'The remove method takes an element out of the page. Other parts stay where they are.', 'html', '<p id="tip">This tip can be closed.</p><button id="close">Close tip</button>\n<script>\n  document.querySelector("#close").addEventListener("click", () => {\n    document.querySelector("#tip")?.remove();\n  });\n</script>', 'The first click removes the tip. Later clicks do nothing because ?. checks that the tip still exists.', 'After removal, a fresh query may return null. Avoid calling remove on a missing value.', 'Click Close tip twice and explain why there is no error.', 'What does ?. protect against here?', 'Trying to remove a tip that is already gone', 'The tip having a long sentence', runnable=True),
 L('Use one listener for a list', 'Events often travel from a child to its parent. A parent listener can handle buttons that are added to a list later.', 'html', '<div id="list"><button data-book="Moon Trip">Choose</button></div><p id="choice"></p>\n<script>\n  document.querySelector("#list").addEventListener("click", (event) => {\n    const button = event.target.closest("button[data-book]");\n    if (button) document.querySelector("#choice").textContent = button.dataset.book;\n  });\n</script>', 'Clicking Choose shows Moon Trip. The listener lives on the parent div.', 'Check that a matching button was found before reading its data. The parent can receive clicks on empty space too.', 'Add another data-book button inside the list.', 'Where is this click listener attached?', 'The list parent', 'A separate listener on every book value', runnable=True),
 L('Keep focus visible', 'Focus marks the control that receives keyboard input. The focus method can move the typing cursor to an input when that helps the reader.', 'html', '<label for="search">Find a book</label><input id="search"><button id="start">Go to search</button>\n<script>\n  document.querySelector("#start").addEventListener("click", () => {\n    document.querySelector("#search").focus();\n  });\n</script>', 'Clicking Go to search moves focus into the search field. You can then type.', 'Do not move focus on every page update. Unexpected jumps make a page hard to use.', 'Use Tab to reach the button, then activate it.', 'What does input.focus() do?', 'Moves keyboard focus to the input', 'Sends the input value to a server', runnable=True),
 L('Read an extra data value', 'A data attribute stores a small extra value on an HTML element. JavaScript reads it through dataset as text.', 'html', '<p id="book" data-pages="40">Garden Days</p>\n<script>\n  const pages = Number(document.querySelector("#book").dataset.pages);\n  console.log(pages + 5);\n</script>', 'The console shows 45. Number changes the text 40 into a number before adding 5.', 'Dataset values are strings. Without Number, adding 5 to "40" would join text instead of adding numbers.', 'Change data-pages to 60 and predict the answer.', 'Why is Number used here?', 'To turn the stored text into a number', 'To count all elements on the page', runnable=True),
 L('Build a tiny counter', 'A page can keep a number in JavaScript and show it in an element. Each click updates the number and then updates the displayed words.', 'html', '<button id="add">Read one more</button><p>Books read: <output id="count">0</output></p>\n<script>\n  let count = 0;\n  document.querySelector("#add").addEventListener("click", () => {\n    count += 1;\n    document.querySelector("#count").textContent = String(count);\n  });\n</script>', 'Three clicks make the output show 3. Reloading this example starts again at zero.', 'This example keeps the count only in memory. It does not save a record after a reload.', 'Add a Reset button that sets count and the output to zero.', 'What happens to this count after a page reload?', 'It starts at zero again', 'It is automatically saved on another device', runnable=True),
])

build('web-components',
 'Web Components let you make your own HTML elements with browser tools. A custom element can group a small piece of behaviour and style. Build one greeting first, then learn how it receives values.',
 'Run these HTML examples in this site\'s HTML playground. Each example defines its own custom element in a fresh page. No extra JavaScript library is needed.',
 'Uses autonomous custom elements, Shadow DOM and standard browser events.', [
 L('Make your own HTML tag', 'A custom element is an HTML tag you define. Its name must contain a hyphen so it does not clash with built-in tags.', 'html', '<hello-reader></hello-reader>\n<script>\n  class HelloReader extends HTMLElement {\n    connectedCallback() { this.textContent = "Hello, reader!"; }\n  }\n  customElements.define("hello-reader", HelloReader);\n</script>', 'The custom tag shows Hello, reader! after it is connected to the page.', 'Register a tag name only once in a document. Use a hyphen in the name.', 'Change the greeting words in connectedCallback.', 'Why is hello-reader a valid custom tag name?', 'It includes a hyphen', 'It begins with a capital letter', slug='introduction', runnable=True),
 L('Know when an element connects', 'connectedCallback runs when a custom element joins a document. It may run again if that same element is removed and added later.', 'html', '<visit-note></visit-note>\n<script>\n  class VisitNote extends HTMLElement {\n    connectedCallback() { this.textContent = "I am on the page."; }\n  }\n  customElements.define("visit-note", VisitNote);\n</script>', 'The note writes its message once it is on the page.', 'Do not assume connection happens only once. Repeated connection should not duplicate timers or listeners.', 'Write a message that describes your own component.', 'Can connectedCallback run again for the same element?', 'Yes, if the element is reconnected', 'No, it can only run once forever', runnable=True),
 L('Read an attribute', 'An attribute is an extra fact written in a tag. A custom element can read it with getAttribute.', 'html', '<reader-name name="Mia"></reader-name>\n<script>\n  class ReaderName extends HTMLElement {\n    connectedCallback() { this.textContent = "Hi, " + (this.getAttribute("name") || "reader"); }\n  }\n  customElements.define("reader-name", ReaderName);\n</script>', 'The tag shows Hi, Mia. Without the name attribute, it uses reader.', 'getAttribute returns text or null. Choose a fallback for a missing attribute.', 'Remove name and check the fallback greeting.', 'What does getAttribute("name") return here?', 'The text Mia', 'The class ReaderName itself', runnable=True),
 L('Watch an attribute change', 'observedAttributes names the attributes a custom element watches. attributeChangedCallback runs when one of those values changes.', 'html', '<score-note score="2"></score-note>\n<script>\n  class ScoreNote extends HTMLElement {\n    static observedAttributes = ["score"];\n    attributeChangedCallback(name, oldValue, newValue) { this.textContent = "Score: " + newValue; }\n  }\n  customElements.define("score-note", ScoreNote);\n  document.querySelector("score-note").setAttribute("score", "5");\n</script>', 'The component ends with Score: 5. Its watched score attribute causes the update.', 'Only listed attributes trigger this callback. Do not set the same attribute endlessly from its own callback.', 'Change the last score value to 9.', 'Which attributes trigger attributeChangedCallback?', 'The attributes listed in observedAttributes', 'Every JavaScript variable on the page', runnable=True),
 L('Create a shadow tree', 'A shadow root is a separate group of page parts inside an element. It helps keep a component\'s internal structure together.', 'html', '<shadow-note></shadow-note>\n<script>\n  class ShadowNote extends HTMLElement {\n    constructor() {\n      super();\n      const root = this.attachShadow({ mode: "open" });\n      const paragraph = document.createElement("p");\n      paragraph.textContent = "Inside the component";\n      root.append(paragraph);\n    }\n  }\n  customElements.define("shadow-note", ShadowNote);\n</script>', 'The note displays a paragraph kept inside its shadow root.', 'Call super before using this in a custom element constructor. A shadow root is not a security boundary.', 'Change the internal paragraph message.', 'What does attachShadow create?', 'An internal shadow root for the component', 'A copy of the entire website', runnable=True),
 L('Keep component styles together', 'Styles inside a shadow root usually apply to its internal elements. They do not select unrelated elements elsewhere on the page.', 'html', '<p>Outside note</p><green-note></green-note>\n<script>\n  class GreenNote extends HTMLElement {\n    constructor() {\n      super();\n      this.attachShadow({ mode: "open" }).innerHTML = "<style>p { color: green; }</style><p>Inside note</p>";\n    }\n  }\n  customElements.define("green-note", GreenNote);\n</script>', 'Only Inside note gets this green rule. The outside paragraph keeps its own style.', 'This example uses a fixed, trusted string. Do not build innerHTML from untrusted user text.', 'Add a bold style to the internal paragraph.', 'Which paragraph is selected by the shadow style?', 'The paragraph inside the shadow root', 'Every paragraph in the whole document', runnable=True),
 L('Leave a slot for content', 'A slot is a place where the user of a component can supply content. Default slot text is used when no content is supplied.', 'html', '<reader-card>A story about the moon</reader-card>\n<script>\n  class ReaderCard extends HTMLElement {\n    constructor() {\n      super();\n      this.attachShadow({ mode: "open" }).innerHTML = "<article><h2>Reading card</h2><slot>No story yet</slot></article>";\n    }\n  }\n  customElements.define("reader-card", ReaderCard);\n</script>', 'The card heading is followed by A story about the moon, the content supplied between its tags.', 'A slot displays supplied content; it does not copy that content into a new string.', 'Remove the supplied story and read the fallback.', 'When is No story yet displayed?', 'When no content is supplied for the slot', 'Whenever the component has a heading', runnable=True),
 L('Give slots names', 'Named slots let a component accept different pieces of content in different places.', 'html', '<book-panel><span slot="title">Moon Trip</span><p>A space story.</p></book-panel>\n<script>\n  class BookPanel extends HTMLElement {\n    constructor() { super(); this.attachShadow({mode:"open"}).innerHTML = `<h2><slot name="title">Book</slot></h2><slot></slot>`; }\n  }\n  customElements.define("book-panel", BookPanel);\n</script>', 'Moon Trip fills the named title slot. The paragraph fills the default slot.', 'The slot attribute on supplied content must match the name attribute of the target slot.', 'Add a second title and story using another book-panel.', 'Where does slot="title" content appear?', 'In the slot whose name is title', 'In every slot at once', runnable=True),
 L('Share a JavaScript property', 'A property can accept a JavaScript value on an element. A setter runs code when that property is assigned.', 'html', '<point-display></point-display>\n<script>\n  class PointDisplay extends HTMLElement {\n    set points(value) { this.textContent = "Points: " + Number(value); }\n  }\n  customElements.define("point-display", PointDisplay);\n  document.querySelector("point-display").points = 7;\n</script>', 'The component shows Points: 7 after the property assignment.', 'A property and an attribute do not automatically update each other. Add that behaviour only when you need it.', 'Assign the points property a new number.', 'Does setting a property always change an HTML attribute too?', 'No, that needs explicit component code', 'Yes, the browser always copies it', runnable=True),
 L('Send a custom event', 'A custom event lets a component tell its surroundings that something happened. Its detail field carries a small value.', 'html', '<choice-button></choice-button><p id="result"></p>\n<script>\n  class ChoiceButton extends HTMLElement {\n    connectedCallback() {\n      const button = document.createElement("button"); button.textContent = "Choose book";\n      button.onclick = () => this.dispatchEvent(new CustomEvent("book-chosen", { detail: "Moon Trip", bubbles: true }));\n      this.replaceChildren(button);\n    }\n  }\n  customElements.define("choice-button", ChoiceButton);\n  document.addEventListener("book-chosen", e => { document.querySelector("#result").textContent = e.detail; });\n</script>', 'Clicking the internal button sends book-chosen. The outer listener shows Moon Trip.', 'Events from inside a shadow root need composed: true to cross that boundary. This example dispatches on the host itself.', 'Change the event detail to another book title.', 'Where is the book title carried by this event?', 'event.detail', 'event.className', runnable=True),
 L('Clean up a repeating job', 'disconnectedCallback runs when a custom element leaves the document. Use it to stop repeating work that should no longer run.', 'html', '<tick-note></tick-note>\n<script>\n  class TickNote extends HTMLElement {\n    connectedCallback() { this.count = 0; this.timer = setInterval(() => { this.textContent = String(++this.count); }, 1000); }\n    disconnectedCallback() { clearInterval(this.timer); }\n  }\n  customElements.define("tick-note", TickNote);\n</script>', 'The number grows once per second. Removing the element stops its timer.', 'Leaving a timer running after removal wastes work. Reconnection should start a fresh timer without leaving an old one behind.', 'Remove the element after a few seconds and explain the cleanup.', 'What should happen to this timer when its element is removed?', 'It should be cleared', 'It should keep running forever', runnable=True),
 L('Style the host with a theme value', 'The :host selector styles the custom element itself. A CSS custom property can pass a theme choice into a shadow tree.', 'html', '<style>themed-note { --note-colour: navy; }</style><themed-note></themed-note>\n<script>\n  class ThemedNote extends HTMLElement {\n    constructor() { super(); this.attachShadow({mode:"open"}).innerHTML = "<style>:host { display:block; color:var(--note-colour, green); padding:1rem; }</style>Read a story today."; }\n  }\n  customElements.define("themed-note", ThemedNote);\n</script>', 'The custom element has padding and navy text. If the custom property is missing, it uses green.', 'Use documented theme properties to customise a component. Avoid depending on the names of private internal elements.', 'Change --note-colour and check the component text.', 'Which value is used when --note-colour is missing?', 'green', 'An empty JavaScript string', runnable=True),
])
